diff --git a/js/packages/host-companion/src/server.ts b/js/packages/host-companion/src/server.ts
new file mode 100644
index 00000000..e22fd118
--- /dev/null
+++ b/js/packages/host-companion/src/server.ts
@@ -0,0 +1,262 @@
+import { createServer, type IncomingMessage, type ServerResponse } from "node:http";
+import type { AddressInfo } from "node:net";
+import { networkInterfaces } from "node:os";
+import {
+  HOST_CONTROL_PROTOCOL_VERSION,
+  HOST_CONTROL_WIRE_ERRORS,
+  isRecord,
+  isWireErrorCode,
+  type HostControlWireErrorCode,
+  type ImplementedHostPlugin,
+} from "@vitadeck/sdk/host-control";
+import { implementCorePlugin } from "./core";
+import { createEventLog, EVENT_WAIT_MS } from "./events";
+
+export const MAX_REQUEST_BYTES = 64 * 1024;
+
+export type HostCompanionOptions = {
+  port: number;
+  host?: string;
+  name: string;
+  platform?: string;
+  /** Loaded after `core`, which is always served. */
+  plugins?: readonly ImplementedHostPlugin[];
+  /** Linked Vita IPs, read per request so a `link` from another process applies at once. */
+  vitas?: () => Promise<readonly string[]>;
+  remoteAddress?: (request: IncomingMessage) => string | undefined;
+  log?: (line: string) => void;
+  /** How long `core.events` waits for an event; shortened in tests. */
+  eventWaitMs?: number;
+};
+
+export type RunningHostCompanion = {
+  port: number;
+  /** Replaces every plugin but `core`, stopping the old ones and starting the new, or throws and keeps them. */
+  setPlugins: (plugins: readonly ImplementedHostPlugin[]) => void;
+  close: () => Promise<void>;
+};
+
+type Reply = { status: number; label: string; outcome: string; body: object };
+
+function fail(label: string, code: HostControlWireErrorCode, message: string): Reply {
+  return { status: HOST_CONTROL_WIRE_ERRORS[code], label, outcome: code, body: { ok: false, code, message } };
+}
+
+export function normalizeAddress(address: string): string {
+  return address.startsWith("::ffff:") ? address.slice("::ffff:".length) : address;
+}
+
+function isLoopback(address: string): boolean {
+  return address === "::1" || address.startsWith("127.");
+}
+
+function ownAddresses(): string[] {
+  return Object.values(networkInterfaces()).flatMap((list) => list?.map((info) => info.address) ?? []);
+}
+
+function readBody(request: IncomingMessage): Promise<Buffer | undefined> {
+  return new Promise((resolve, reject) => {
+    const chunks: Buffer[] = [];
+    let size = 0;
+    // Drains past the limit so the 413 reaches a client that is still sending.
+    request.on("data", (chunk: Buffer) => {
+      size += chunk.length;
+      if (size <= MAX_REQUEST_BYTES) chunks.push(chunk);
+    });
+    request.on("end", () => {
+      resolve(size <= MAX_REQUEST_BYTES ? Buffer.concat(chunks) : undefined);
+    });
+    request.on("error", reject);
+  });
+}
+
+/** Matched by shape, since a Host Plugin Package throws its own bundled copy of `HostCommandError`. */
+function wireErrorCode(error: unknown): HostControlWireErrorCode | undefined {
+  return error instanceof Error && error.name === "HostCommandError" && "code" in error && isWireErrorCode(error.code)
+    ? error.code
+    : undefined;
+}
+
+function parseJson(text: string): unknown {
+  try {
+    return JSON.parse(text);
+  } catch {
+    return undefined;
+  }
+}
+
+export async function startHostCompanion(options: HostCompanionOptions): Promise<RunningHostCompanion> {
+  const {
+    name,
+    platform = process.platform,
+    vitas = () => Promise.resolve([]),
+    remoteAddress = (request: IncomingMessage) => request.socket.remoteAddress,
+    log = (line) => {
+      console.log(line);
+    },
+  } = options;
+
+  const events = createEventLog(options.eventWaitMs ?? EVENT_WAIT_MS);
+  let plugins = new Map<string, ImplementedHostPlugin>();
+  const core = implementCorePlugin(name, platform, () => [...plugins.values()], events);
+
+  // Each plugin's lifecycle runs while it is loaded; an emit after its stop is dropped.
+  function startPlugins(loaded: readonly ImplementedHostPlugin[]): () => void {
+    let running = true;
+    const stops = loaded.flatMap((plugin) => {
+      try {
+        const stop = plugin.start?.((event, data) => {
+          if (running) events.emit(plugin.id, event, data);
+        });
+        return stop ? [stop] : [];
+      } catch (error) {
+        log(`Plugin ${plugin.id} failed to start: ${error instanceof Error ? error.message : String(error)}`);
+        return [];
+      }
+    });
+    return () => {
+      if (!running) return;
+      running = false;
+      for (const stop of stops) {
+        try {
+          stop();
+        } catch (error) {
+          log(`A plugin failed to stop: ${error instanceof Error ? error.message : String(error)}`);
+        }
+      }
+    };
+  }
+
+  function byId(next: readonly ImplementedHostPlugin[]): Map<string, ImplementedHostPlugin> {
+    const map = new Map([[core.id, core]]);
+    for (const plugin of next) {
+      if (map.has(plugin.id)) throw new Error(`Two loaded plugins share the id ${plugin.id}.`);
+      map.set(plugin.id, plugin);
+    }
+    return map;
+  }
+
+  plugins = byId(options.plugins ?? []);
+  let stopRunning = startPlugins([]);
+
+  function setPlugins(next: readonly ImplementedHostPlugin[]): void {
+    const loaded = byId(next);
+    stopRunning();
+    plugins = loaded;
+    stopRunning = startPlugins(next);
+  }
+
+  async function isAllowed(peer: string): Promise<boolean> {
+    const linked = await vitas();
+    return linked.length === 0 || isLoopback(peer) || linked.includes(peer) || ownAddresses().includes(peer);
+  }
+
+  async function reply(request: IncomingMessage, peer: string): Promise<Reply> {
+    const route = `${request.method ?? "?"} ${request.url ?? "?"}`;
+    if (!(await isAllowed(peer))) {
+      // Discards the body unbuffered, so a peer that is not linked costs no memory.
+      request.resume();
+      return fail(route, "forbidden", "This Host Companion only answers the VitaDeck it is linked with.");
+    }
+    const body = await readBody(request);
+    // Every status comes from HOST_CONTROL_WIRE_ERRORS, so an unknown route is an unknown command.
+    if (new URL(request.url ?? "/", "http://companion").pathname !== "/command") {
+      return fail(route, "unknown_command", "This Host Companion serves only POST /command.");
+    }
+    if (request.method !== "POST") return fail(route, "malformed_request", "Send commands with POST /command.");
+    const contentType = request.headers["content-type"]?.split(";")[0]?.trim().toLowerCase();
+    if (contentType !== "application/json") {
+      return fail(route, "malformed_request", "Send commands with Content-Type: application/json.");
+    }
+    if (body === undefined) {
+      return fail(route, "payload_too_large", `A command request may be at most ${MAX_REQUEST_BYTES} bytes.`);
+    }
+
+    const envelope = parseJson(body.toString("utf8"));
+    if (!isRecord(envelope) || typeof envelope.protocolVersion !== "number") {
+      return fail(route, "malformed_request", "The request body is not a Host Control command.");
+    }
+    if (envelope.protocolVersion !== HOST_CONTROL_PROTOCOL_VERSION) {
+      return fail(
+        route,
+        "unsupported_protocol_version",
+        `This Host Companion speaks Host Control protocol version ${HOST_CONTROL_PROTOCOL_VERSION}.`,
+      );
+    }
+    if (typeof envelope.plugin !== "string" || typeof envelope.command !== "string") {
+      return fail(route, "malformed_request", "The request body is not a Host Control command.");
+    }
+
+    const label = `${envelope.plugin}.${envelope.command}`;
+    const plugin = plugins.get(envelope.plugin);
+    if (!plugin) return fail(label, "unknown_plugin", `This Host Companion has no plugin ${envelope.plugin}.`);
+    const command = plugin.commands.get(envelope.command);
+    if (!command) return fail(label, "unknown_command", `Plugin ${plugin.id} has no command ${envelope.command}.`);
+    if (!command.isPayload(envelope.payload)) return fail(label, "invalid_payload", `Invalid payload for ${label}.`);
+
+    try {
+      const result = await command.run(envelope.payload);
+      return { status: 200, label, outcome: "ok", body: { ...result, ok: true } };
+    } catch (error) {
+      const message = error instanceof Error ? error.message : String(error);
+      return fail(label, wireErrorCode(error) ?? "command_failed", message);
+    }
+  }
+
+  async function answer(request: IncomingMessage, response: ServerResponse): Promise<void> {
+    const started = performance.now();
+    const peer = normalizeAddress(remoteAddress(request) ?? "unknown");
+    let result: Reply;
+    try {
+      result = await reply(request, peer);
+    } catch (error) {
+      result = fail("?", "command_failed", String(error));
+    }
+    const text = JSON.stringify(result.body);
+    response.writeHead(result.status, {
+      "Content-Type": "application/json",
+      "Content-Length": Buffer.byteLength(text),
+      Connection: "close",
+    });
+    response.end(text);
+    const ms = Math.round(performance.now() - started);
+    log(`${new Date().toISOString()} ${peer} ${result.label} ${result.outcome} ${ms}ms`);
+  }
+
+  const server = createServer((request, response) => {
+    void answer(request, response);
+  });
+
+  await new Promise<void>((resolve, reject) => {
+    server.once("error", (error: NodeJS.ErrnoException) => {
+      reject(
+        error.code === "EADDRINUSE"
+          ? new Error(`Port ${options.port} is already in use. Stop the other program or choose another --port.`)
+          : error,
+      );
+    });
+    server.listen(options.port, options.host ?? "0.0.0.0", () => {
+      resolve();
+    });
+  });
+  // Lifecycles start once the port is bound, so a busy port leaves no plugin timer keeping the process alive.
+  stopRunning = startPlugins(options.plugins ?? []);
+
+  return {
+    port: (server.address() as AddressInfo).port,
+    setPlugins,
+    close: () =>
+      new Promise((resolve, reject) => {
+        events.close();
+        stopRunning();
+        if (!server.listening) {
+          resolve();
+          return;
+        }
+        server.close((error) => {
+          if (error) reject(error);
+          else resolve();
+        });
+      }),
+  };
+}

diff --git a/js/packages/host-companion/src/core.ts b/js/packages/host-companion/src/core.ts
new file mode 100644
index 00000000..0734f51e
--- /dev/null
+++ b/js/packages/host-companion/src/core.ts
@@ -0,0 +1,35 @@
+import {
+  HOST_CONTROL_PROTOCOL_VERSION,
+  HostCommandError,
+  corePlugin,
+  implementHostPlugin,
+  type ImplementedHostPlugin,
+} from "@vitadeck/sdk/host-control";
+import type { EventLog } from "./events";
+
+export function implementCorePlugin(
+  name: string,
+  platform: string,
+  loadedPlugins: () => readonly ImplementedHostPlugin[],
+  events: EventLog,
+): ImplementedHostPlugin {
+  return implementHostPlugin(corePlugin, {
+    capabilities: () => ({
+      protocolVersion: HOST_CONTROL_PROTOCOL_VERSION,
+      name,
+      platform,
+      plugins: loadedPlugins().map((plugin) => ({ id: plugin.id, commands: [...plugin.commands.keys()] })),
+    }),
+    echo: ({ text }) => ({ text }),
+    events: ({ plugin, after }) => {
+      if (plugin !== corePlugin.id && !loadedPlugins().some((loaded) => loaded.id === plugin)) {
+        throw new HostCommandError("unknown_plugin", `This Host Companion has no plugin ${plugin}.`);
+      }
+      return events.wait(plugin, after);
+    },
+    notify: ({ text }) => {
+      events.emit(corePlugin.id, "notice", { text });
+      return {};
+    },
+  });
+}

diff --git a/js/packages/host-companion/src/link.ts b/js/packages/host-companion/src/link.ts
new file mode 100644
index 00000000..03b2defc
--- /dev/null
+++ b/js/packages/host-companion/src/link.ts
@@ -0,0 +1,153 @@
+import { createSocket } from "node:dgram";
+import {
+  HOST_CONTROL_PROTOCOL_VERSION,
+  corePlugin,
+  createHostClient,
+  isRecord,
+  type HostControlLinkRequest,
+} from "@vitadeck/sdk/host-control";
+import { loadConfig, saveConfig } from "./config";
+
+export const DEFAULT_VITA_LINK_PORT = 8787;
+const LINK_TIMEOUT_MS = 5000;
+
+export type LinkOptions = {
+  configPath: string;
+  /** The port `start` listens on. Defaults to the config's. */
+  port?: number;
+  /** The IP to advertise. Defaults to the config's, then to the interface routed to the Vita. */
+  advertise?: string;
+  /** Update an existing link only. A Vita that no longer has it is dropped from the config. */
+  relink?: boolean;
+};
+
+/** `retry` is true when the Vita did not answer, e.g. because it is off. */
+export type LinkOutcome = { ok: true; message: string } | { ok: false; message: string; retry: boolean };
+
+export function parseVitaAddress(address: string): { host: string; port: number } | undefined {
+  let url: URL;
+  try {
+    url = new URL(`http://${address}`);
+  } catch {
+    return undefined;
+  }
+  if (url.pathname !== "/" || url.search !== "" || url.username !== "" || url.hash !== "") return undefined;
+  return { host: url.hostname, port: url.port === "" ? DEFAULT_VITA_LINK_PORT : Number(url.port) };
+}
+
+/** Connecting a UDP socket sends nothing, but makes the OS pick the local interface that routes to `host`. */
+async function route(host: string, port: number): Promise<{ local: string; remote: string }> {
+  const socket = createSocket("udp4");
+  try {
+    await new Promise<void>((resolve, reject) => {
+      socket.once("error", reject);
+      socket.connect(port, host, () => {
+        resolve();
+      });
+    });
+    return { local: socket.address().address, remote: socket.remoteAddress().address };
+  } finally {
+    socket.close();
+  }
+}
+
+async function postLink(url: string, request: HostControlLinkRequest): Promise<{ status: number; body: unknown }> {
+  const response = await fetch(url, {
+    method: "POST",
+    headers: { "Content-Type": "application/json" },
+    body: JSON.stringify(request),
+    signal: AbortSignal.timeout(LINK_TIMEOUT_MS),
+  });
+  const text = await response.text();
+  try {
+    return { status: response.status, body: JSON.parse(text) };
+  } catch {
+    return { status: response.status, body: undefined };
+  }
+}
+
+/** Tells the VitaDeck at `vitaAddress` to send Host Control commands to this computer's running companion. */
+export async function linkVita(vitaAddress: string, options: LinkOptions): Promise<LinkOutcome> {
+  const target = parseVitaAddress(vitaAddress);
+  if (!target)
+    return {
+      ok: false,
+      message: `${vitaAddress} is not an address like 192.168.1.177 or 192.168.1.177:8787.`,
+      retry: false,
+    };
+
+  const config = await loadConfig(options.configPath);
+  const port = options.port ?? config.port;
+
+  const self = createHostClient(corePlugin, { url: `http://127.0.0.1:${port}/`, timeoutMs: 2000 });
+  const capabilities = await self.capabilities();
+  if (!capabilities.ok) {
+    return {
+      ok: false,
+      message: `No Host Companion answers on port ${port} (${capabilities.message}). Run \`vitadeck-host-companion start\` first.`,
+      retry: false,
+    };
+  }
+
+  let routed: { local: string; remote: string };
+  try {
+    routed = await route(target.host, target.port);
+  } catch (error) {
+    return { ok: false, message: `Cannot reach ${target.host}: ${String(error)}`, retry: true };
+  }
+
+  const advertised = options.advertise ?? config.advertise ?? routed.local;
+  const request: HostControlLinkRequest = {
+    protocolVersion: HOST_CONTROL_PROTOCOL_VERSION,
+    id: config.id,
+    name: config.name,
+    url: `http://${advertised}:${port}/`,
+    ...(options.relink && { relink: true }),
+  };
+  const linkUrl = `http://${routed.remote}:${target.port}/link`;
+
+  let answer: { status: number; body: unknown };
+  try {
+    answer = await postLink(linkUrl, request);
+  } catch (error) {
+    const reason = error instanceof Error && error.cause instanceof Error ? error.cause.message : String(error);
+    return {
+      ok: false,
+      message: `Could not reach VitaDeck at ${linkUrl} (${reason}). Check that Upload and link is on in the VitaDeck Shell, and that the address matches the one it shows.`,
+      retry: true,
+    };
+  }
+
+  const { body } = answer;
+  if (!isRecord(body) || typeof body.ok !== "boolean") {
+    return {
+      ok: false,
+      message: `${linkUrl} answered HTTP ${answer.status} without a Host Control result.`,
+      retry: false,
+    };
+  }
+  if (!body.ok) {
+    const code = typeof body.code === "string" ? body.code : "unknown";
+    const message = typeof body.message === "string" ? body.message : "No reason given.";
+    if (options.relink && code === "unknown_link") {
+      // Read again: a `link` in another process may have changed the config while this request was out.
+      const latest = await loadConfig(options.configPath);
+      await saveConfig(options.configPath, { ...latest, vitas: latest.vitas.filter((vita) => vita !== routed.remote) });
+      return {
+        ok: false,
+        message: `VitaDeck at ${routed.remote} forgot this computer, so it is no longer a linked Vita here. Run \`vitadeck-host-companion link ${routed.remote}\` to link it again.`,
+        retry: false,
+      };
+    }
+    return { ok: false, message: `VitaDeck refused the link (${code}): ${message}`, retry: false };
+  }
+
+  const latest = await loadConfig(options.configPath);
+  if (!latest.vitas.includes(routed.remote)) {
+    await saveConfig(options.configPath, { ...latest, vitas: [...latest.vitas, routed.remote] });
+  }
+  return {
+    ok: true,
+    message: `${options.relink ? "Relinked" : "Linked"} "${config.name}" with VitaDeck at ${routed.remote}. It will send commands to ${request.url}`,
+  };
+}

diff --git a/js/packages/host-companion/src/config.ts b/js/packages/host-companion/src/config.ts
new file mode 100644
index 00000000..96732624
--- /dev/null
+++ b/js/packages/host-companion/src/config.ts
@@ -0,0 +1,96 @@
+import { randomUUID } from "node:crypto";
+import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
+import os from "node:os";
+import path from "node:path";
+import { isRecord } from "@vitadeck/sdk/host-control";
+
+export type HostCompanionConfig = {
+  /** Generated once; VitaDeck keeps one link per id. */
+  id: string;
+  name: string;
+  port: number;
+  /** The IP to put in the link URL instead of the one routed to the Vita. */
+  advertise: string | null;
+  /** Linked Vita IPs. Once non-empty, only these, loopback and this computer's addresses get answers. */
+  vitas: string[];
+};
+
+export const DEFAULT_CONFIG_PATH = path.join(os.homedir(), ".vitadeck", "host-companion.json");
+export const DEFAULT_PORT = 8797;
+
+/** Where `install` puts Host Plugin Packages: `plugins/` next to the config file. */
+export function installedPluginsDir(configPath: string): string {
+  return path.join(path.dirname(configPath), "plugins");
+}
+
+function defaults(): HostCompanionConfig {
+  return {
+    id: randomUUID(),
+    name: os.hostname(),
+    port: DEFAULT_PORT,
+    advertise: null,
+    vitas: [],
+  };
+}
+
+export function isPort(value: unknown): value is number {
+  return Number.isInteger(value) && typeof value === "number" && value > 0 && value <= 65_535;
+}
+
+const isNonEmptyString = (value: unknown): value is string => typeof value === "string" && value !== "";
+const isStringArray = (value: unknown): value is string[] =>
+  Array.isArray(value) && value.every((item) => typeof item === "string");
+
+const validators: { [K in keyof HostCompanionConfig]: (value: unknown) => value is HostCompanionConfig[K] } = {
+  id: isNonEmptyString,
+  name: isNonEmptyString,
+  port: isPort,
+  advertise: (value): value is string | null => value === null || isNonEmptyString(value),
+  vitas: isStringArray,
+};
+
+/** Reads the config file; missing fields take their defaults, wrongly typed ones throw. */
+export async function readConfig(file: string): Promise<{ config: HostCompanionConfig; complete: boolean }> {
+  let raw: unknown;
+  try {
+    raw = JSON.parse(await readFile(file, "utf8"));
+  } catch (error) {
+    if (error instanceof SyntaxError) throw new Error(`${file} is not valid JSON.`, { cause: error });
+    throw error;
+  }
+  if (!isRecord(raw)) throw new Error(`${file} must hold a JSON object.`);
+
+  const config = defaults();
+  let complete = true;
+  for (const key of Object.keys(validators) as (keyof HostCompanionConfig)[]) {
+    if (!(key in raw)) {
+      complete = false;
+      continue;
+    }
+    const value = raw[key];
+    if (!validators[key](value)) throw new Error(`${file}: "${key}" has the wrong type.`);
+    Object.assign(config, { [key]: value });
+  }
+  return { config, complete };
+}
+
+export async function saveConfig(file: string, config: HostCompanionConfig): Promise<void> {
+  await mkdir(path.dirname(file), { recursive: true });
+  const temporary = `${file}.${process.pid}.tmp`;
+  await writeFile(temporary, `${JSON.stringify(config, null, 2)}\n`);
+  await rename(temporary, file);
+}
+
+/** Reads the config, creating it or filling in missing fields on first use. */
+export async function loadConfig(file: string): Promise<HostCompanionConfig> {
+  try {
+    const { config, complete } = await readConfig(file);
+    if (!complete) await saveConfig(file, config);
+    return config;
+  } catch (error) {
+    if (!(error instanceof Error && "code" in error && error.code === "ENOENT")) throw error;
+    const config = defaults();
+    await saveConfig(file, config);
+    return config;
+  }
+}

diff --git a/js/packages/host-companion/src/system-stats.ts b/js/packages/host-companion/src/system-stats.ts
new file mode 100644
index 00000000..5a0baa35
--- /dev/null
+++ b/js/packages/host-companion/src/system-stats.ts
@@ -0,0 +1,60 @@
+import { execFile } from "node:child_process";
+import os from "node:os";
+import { setTimeout as sleep } from "node:timers/promises";
+import { implementHostPlugin, systemStatsPlugin } from "@vitadeck/sdk/host-control";
+
+type CpuSample = { idle: number; total: number };
+
+function sampleCpus(): CpuSample {
+  let idle = 0;
+  let total = 0;
+  for (const { times } of os.cpus()) {
+    idle += times.idle;
+    total += times.user + times.nice + times.sys + times.idle + times.irq;
+  }
+  return { idle, total };
+}
+
+const roundTenth = (value: number) => Math.round(value * 10) / 10;
+
+let previous: CpuSample | undefined;
+
+/** Busy share of CPU time since the previous read; the first read samples twice, 200 ms apart. */
+async function cpuPercent(): Promise<number> {
+  if (!previous) {
+    previous = sampleCpus();
+    await sleep(200);
+  }
+  const current = sampleCpus();
+  const total = current.total - previous.total;
+  const idle = current.idle - previous.idle;
+  previous = current;
+  return total > 0 ? roundTenth(((total - idle) / total) * 100) : 0;
+}
+
+// Node counts macOS's reclaimable file cache as used, so a Mac would always read near 100%. vm_stat's free, inactive
+// and speculative pages are what Activity Monitor treats as available.
+async function availableMemoryBytes(): Promise<number> {
+  if (process.platform !== "darwin") return os.freemem();
+  const stdout = await new Promise<string>((resolve, reject) => {
+    execFile("vm_stat", (error, output) => {
+      if (error) reject(new Error(`vm_stat failed: ${error.message}`));
+      else resolve(output);
+    });
+  });
+  const pageSize = Number(/page size of (\d+) bytes/u.exec(stdout)?.[1] ?? 4096);
+  const pages = (label: string) => Number(new RegExp(`${label}:\\s+(\\d+)`, "u").exec(stdout)?.[1] ?? 0);
+  return (pages("Pages free") + pages("Pages inactive") + pages("Pages speculative")) * pageSize;
+}
+
+export const systemStats = implementHostPlugin(systemStatsPlugin, {
+  read: async () => {
+    const memoryTotalBytes = os.totalmem();
+    return {
+      cpuPercent: await cpuPercent(),
+      memoryUsedPercent: roundTenth(((memoryTotalBytes - (await availableMemoryBytes())) / memoryTotalBytes) * 100),
+      memoryTotalBytes,
+      uptimeSeconds: Math.floor(os.uptime()),
+    };
+  },
+});

diff --git a/js/packages/host-companion/src/cli.ts b/js/packages/host-companion/src/cli.ts
new file mode 100644
index 00000000..d79aed99
--- /dev/null
+++ b/js/packages/host-companion/src/cli.ts
@@ -0,0 +1,265 @@
+import { watch } from "node:fs";
+import { cp, mkdir, mkdtemp, rename, rm } from "node:fs/promises";
+import { networkInterfaces } from "node:os";
+import path from "node:path";
+import { parseArgs } from "node:util";
+import { corePlugin, createHostClient, type ImplementedHostPlugin } from "@vitadeck/sdk/host-control";
+import { DEFAULT_CONFIG_PATH, installedPluginsDir, isPort, loadConfig, readConfig } from "./config";
+import { linkVita } from "./link";
+import {
+  HOST_PLUGIN_ARCHIVE_EXTENSION,
+  HOST_PLUGIN_EXTENSION,
+  extractHostPluginArchive,
+  hostPluginPackagesIn,
+  isHostPluginId,
+  loadHostPluginPackage,
+} from "./plugin";
+import { startHostCompanion } from "./server";
+import { systemStats } from "./system-stats";
+
+const USAGE = `Usage: vitadeck-host-companion <command>
+
+  start [--port N] [--plugin <name.vdplugin|dir>]... [--config <path>]
+      Serve Host Control commands on 0.0.0.0, port 8797 by default. Loads the built-in plugins, the installed
+      ones, and each --plugin package or every .vdplugin package in a --plugin folder, and reloads them when
+      they change.
+  link <vita-address>[:port] [--port N] [--advertise <ip>] [--config <path>]
+      Link the VitaDeck showing that address (port 8787 by default) with the running companion.
+  install <name.vdplugin.zip|name.vdplugin> [--config <path>]
+      Install a Host Plugin Package that a Deck App's author built. It runs with your permissions on this
+      computer.
+  remove <plugin-id> [--config <path>]
+      Uninstall a plugin.
+  notify <text> [--port N] [--config <path>]
+      Send a notice to every Deck App watching this computer, e.g. after a build: make && vitadeck-host-companion notify "Build done".`;
+
+const BUILT_IN_PLUGINS: readonly ImplementedHostPlugin[] = [systemStats];
+const BUILT_IN_IDS = new Set(["core", ...BUILT_IN_PLUGINS.map((plugin) => plugin.id)]);
+const RELOAD_QUIET_MS = 200;
+const RELINK_RETRY_MS = 30_000;
+
+// `pnpm --dir js host-companion` runs from js/, so paths are relative to INIT_CWD, where the user typed it. Anywhere
+// else, a Deck App's `host` script included, they are relative to the working directory.
+const userCwd =
+  process.env.npm_lifecycle_event === "host-companion" ? (process.env.INIT_CWD ?? process.cwd()) : process.cwd();
+
+function parsePort(value: string | undefined): number | undefined {
+  if (value === undefined) return undefined;
+  const port = Number(value);
+  if (!isPort(port)) throw new Error(`--port must be a number from 1 to 65535, not ${value}.`);
+  return port;
+}
+
+function lanUrls(port: number): string[] {
+  const addresses = Object.values(networkInterfaces())
+    .flatMap((list) => list ?? [])
+    .filter((info) => info.family === "IPv4" && !info.internal)
+    .map((info) => `http://${info.address}:${port}/`);
+  return addresses.length > 0 ? addresses : [`http://127.0.0.1:${port}/`];
+}
+
+function watchFailed(dir: string) {
+  return (error: Error) => {
+    console.error(`Stopped watching ${dir} for plugin changes: ${error.message}`);
+  };
+}
+
+/**
+ * Sends each linked Vita this companion's current URL, so a new IP or port reaches them without `link`. Attempts,
+ * retries included, run one at a time, since each outcome rewrites the config; a Vita that does not answer is retried
+ * until it does.
+ */
+function relink(vitas: readonly string[], configPath: string, port: number): void {
+  let queue = Promise.resolve();
+  const run = async (vita: string, retrying: boolean) => {
+    try {
+      const outcome = await linkVita(vita, { configPath, port, relink: true });
+      if (outcome.ok || !outcome.retry) {
+        console.log(outcome.message);
+        return;
+      }
+      if (!retrying) console.log(`${outcome.message} Retrying every ${RELINK_RETRY_MS / 1000} s.`);
+      setTimeout(() => {
+        attempt(vita, true);
+      }, RELINK_RETRY_MS);
+    } catch (error) {
+      console.error(`Could not relink ${vita}: ${error instanceof Error ? error.message : String(error)}`);
+    }
+  };
+  const attempt = (vita: string, retrying: boolean) => {
+    queue = queue.then(() => run(vita, retrying));
+  };
+  for (const vita of vitas) attempt(vita, false);
+}
+
+function describe(plugins: readonly ImplementedHostPlugin[]): string {
+  return ["core", ...plugins.map((plugin) => plugin.id)].join(", ");
+}
+
+async function start(values: { port?: string; plugin?: string[] }, configPath: string): Promise<void> {
+  const config = await loadConfig(configPath);
+  const pluginsDir = installedPluginsDir(configPath);
+  await mkdir(pluginsDir, { recursive: true });
+  const extra = (values.plugin ?? []).map((given) => path.resolve(userCwd, given));
+  const archive = extra.find((entry) => entry.endsWith(HOST_PLUGIN_ARCHIVE_EXTENSION));
+  if (archive) throw new Error(`--plugin takes a ${HOST_PLUGIN_EXTENSION} folder; install ${archive} instead.`);
+  // A path ending in .vdplugin is one package; any other path is a folder of them, like a Deck App's dist/.
+  const extraPackages = extra.filter((entry) => entry.endsWith(HOST_PLUGIN_EXTENSION));
+  const extraDirs = extra.filter((entry) => !entry.endsWith(HOST_PLUGIN_EXTENSION));
+  const loadPlugins = async () => {
+    const listed = await Promise.all([pluginsDir, ...extraDirs].map((dir) => hostPluginPackagesIn(dir)));
+    // A --plugin package replaces an installed plugin with the same id, so an author can work on one they installed.
+    const loaded = await Promise.all([...listed.flat(), ...extraPackages].map((dir) => loadHostPluginPackage(dir)));
+    const custom = new Map(loaded.map((plugin) => [plugin.id, plugin]));
+    return [...BUILT_IN_PLUGINS, ...custom.values()];
+  };
+
+  const plugins = await loadPlugins();
+  const companion = await startHostCompanion({
+    port: parsePort(values.port) ?? config.port,
+    name: config.name,
+    plugins,
+    vitas: () =>
+      readConfig(configPath).then(
+        (current) => current.config.vitas,
+        () => config.vitas,
+      ),
+  });
+  console.log(`Host Companion "${config.name}" is listening on ${lanUrls(companion.port).join(", ")}`);
+  console.log(`Plugins: ${describe(plugins)}`);
+  console.log(
+    config.vitas.length > 0
+      ? `Linked Vitas: ${config.vitas.join(", ")}`
+      : "Link a Vita with: vitadeck-host-companion link <vita-address> (the address under Upload and link in the VitaDeck Shell)",
+  );
+  relink(config.vitas, configPath, companion.port);
+
+  // Parent folders, recursively: a rebuild or reinstall replaces the package folder, which ends a watch on it.
+  let timer: NodeJS.Timeout | undefined;
+  const reload = () => {
+    clearTimeout(timer);
+    timer = setTimeout(() => {
+      void (async () => {
+        try {
+          const next = await loadPlugins();
+          companion.setPlugins(next);
+          console.log(`Reloaded plugins: ${describe(next)}`);
+        } catch (error) {
+          console.error(`Kept the previous plugins: ${error instanceof Error ? error.message : String(error)}`);
+        }
+      })();
+    }, RELOAD_QUIET_MS);
+  };
+  const watched = [
+    ...[pluginsDir, ...extraDirs].map((dir) => ({ dir, prefix: "" })),
+    ...extraPackages.map((entry) => ({ dir: path.dirname(entry), prefix: path.basename(entry) })),
+  ];
+  for (const { dir, prefix } of watched) {
+    watch(dir, { recursive: true }, (_event, name) => {
+      if (name !== null && name.startsWith(prefix) && name.includes(HOST_PLUGIN_EXTENSION)) reload();
+    }).on("error", watchFailed(dir));
+  }
+}
+
+async function install(given: string, configPath: string): Promise<void> {
+  const source = path.resolve(userCwd, given);
+  if (!source.endsWith(HOST_PLUGIN_ARCHIVE_EXTENSION) && !source.endsWith(HOST_PLUGIN_EXTENSION)) {
+    throw new Error(`${given} is not a ${HOST_PLUGIN_ARCHIVE_EXTENSION} archive or a ${HOST_PLUGIN_EXTENSION} folder.`);
+  }
+  const dir = installedPluginsDir(configPath);
+  await mkdir(dir, { recursive: true });
+  // Staged in a folder the loader skips, then renamed into place, so a running companion never loads half a package.
+  const staging = await mkdtemp(path.join(dir, ".install-"));
+  try {
+    let staged = path.join(staging, path.basename(source));
+    if (source.endsWith(HOST_PLUGIN_ARCHIVE_EXTENSION)) staged = await extractHostPluginArchive(source, staging);
+    else await cp(source, staged, { recursive: true });
+    const plugin = await loadHostPluginPackage(staged);
+    if (BUILT_IN_IDS.has(plugin.id)) throw new Error(`${plugin.id} is a built-in plugin and cannot be replaced.`);
+    const target = path.join(dir, `${plugin.id}${HOST_PLUGIN_EXTENSION}`);
+    await rm(target, { recursive: true, force: true });
+    await rename(staged, target);
+    console.log(
+      `Installed ${plugin.id} (${[...plugin.commands.keys()].join(", ")}). A running Host Companion loads it now.`,
+    );
+  } finally {
+    await rm(staging, { recursive: true, force: true });
+  }
+}
+
+async function remove(id: string, configPath: string): Promise<void> {
+  if (!isHostPluginId(id)) throw new Error(`${id} is not a plugin id.`);
+  try {
+    await rm(path.join(installedPluginsDir(configPath), `${id}${HOST_PLUGIN_EXTENSION}`), { recursive: true });
+  } catch (error) {
+    if (error instanceof Error && "code" in error && error.code === "ENOENT") {
+      throw new Error(`No plugin ${id} is installed.`, { cause: error });
+    }
+    throw error;
+  }
+  console.log(`Removed ${id}.`);
+}
+
+async function notify(text: string, port: number | undefined, configPath: string): Promise<number> {
+  const target = port ?? (await loadConfig(configPath)).port;
+  const sent = await createHostClient(corePlugin, { url: `http://127.0.0.1:${target}/` }).notify({ text });
+  if (sent.ok) return 0;
+  console.error(
+    `No Host Companion took the notice on port ${target} (${sent.message}). Is \`vitadeck-host-companion start\` running?`,
+  );
+  return 1;
+}
+
+async function main(): Promise<number> {
+  const { positionals, values } = parseArgs({
+    allowPositionals: true,
+    options: {
+      port: { type: "string" },
+      plugin: { type: "string", multiple: true },
+      config: { type: "string" },
+      advertise: { type: "string" },
+      help: { type: "boolean", short: "h" },
+    },
+  });
+  const [command, ...rest] = positionals;
+  const [arg] = rest;
+  const configPath = values.config === undefined ? DEFAULT_CONFIG_PATH : path.resolve(userCwd, values.config);
+
+  if (values.help) {
+    console.log(USAGE);
+    return 0;
+  }
+  if (command === "start" && rest.length === 0) {
+    await start(values, configPath);
+    return 0;
+  }
+  if (command === "link" && rest.length === 1 && arg !== undefined) {
+    const outcome = await linkVita(arg, {
+      configPath,
+      port: parsePort(values.port),
+      advertise: values.advertise,
+    });
+    (outcome.ok ? console.log : console.error)(outcome.message);
+    return outcome.ok ? 0 : 1;
+  }
+  if (command === "install" && rest.length === 1 && arg !== undefined) {
+    await install(arg, configPath);
+    return 0;
+  }
+  if (command === "notify" && rest.length === 1 && arg !== undefined) {
+    return notify(arg, parsePort(values.port), configPath);
+  }
+  if (command === "remove" && rest.length === 1 && arg !== undefined) {
+    await remove(arg, configPath);
+    return 0;
+  }
+  console.error(USAGE);
+  return 1;
+}
+
+try {
+  process.exitCode = await main();
+} catch (error) {
+  console.error(error instanceof Error ? error.message : String(error));
+  process.exitCode = 1;
+}

diff --git a/js/packages/host-companion/test/link.test.ts b/js/packages/host-companion/test/link.test.ts
new file mode 100644
index 00000000..d82acfaa
--- /dev/null
+++ b/js/packages/host-companion/test/link.test.ts
@@ -0,0 +1,180 @@
+import assert from "node:assert/strict";
+import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
+import { createServer, type Server } from "node:http";
+import type { AddressInfo } from "node:net";
+import os from "node:os";
+import path from "node:path";
+import test from "node:test";
+import { fileURLToPath } from "node:url";
+import { loadConfig, saveConfig } from "../src/config";
+import { linkVita, parseVitaAddress } from "../src/link";
+import { startHostCompanion } from "../src/server";
+
+type Fixture = { status: number; response: unknown };
+
+const fixturesDir = fileURLToPath(new URL("../../../../tests/fixtures/host-control/", import.meta.url));
+
+async function fixture(name: string): Promise<Fixture> {
+  return JSON.parse(await readFile(`${fixturesDir}${name}.json`, "utf8")) as Fixture;
+}
+
+async function listen(server: Server): Promise<number> {
+  await new Promise<void>((resolve) => {
+    server.listen(0, "127.0.0.1", resolve);
+  });
+  return (server.address() as AddressInfo).port;
+}
+
+function close(server: Server): Promise<void> {
+  return new Promise((resolve) => {
+    server.close(() => {
+      resolve();
+    });
+  });
+}
+
+/** A port nothing listens on. */
+async function freePort(): Promise<number> {
+  const server = createServer();
+  const port = await listen(server);
+  await close(server);
+  return port;
+}
+
+/** A VitaDeck link endpoint that records requests and answers with a fixture. */
+async function stubVita(t: test.TestContext, fx: Fixture) {
+  const received: { method?: string; url?: string; body: Record<string, unknown> }[] = [];
+  const server = createServer((request, response) => {
+    let body = "";
+    request.on("data", (chunk: Buffer) => {
+      body += chunk.toString("utf8");
+    });
+    request.on("end", () => {
+      received.push({ method: request.method, url: request.url, body: JSON.parse(body) as Record<string, unknown> });
+      response.writeHead(fx.status, { "Content-Type": "application/json", Connection: "close" });
+      response.end(JSON.stringify(fx.response));
+    });
+  });
+  const port = await listen(server);
+  t.after(() => close(server));
+  return { port, received };
+}
+
+async function setup(t: test.TestContext, withCompanion = true) {
+  const dir = await mkdtemp(path.join(os.tmpdir(), "host-companion-"));
+  t.after(() => rm(dir, { recursive: true, force: true }));
+  const configPath = path.join(dir, "config.json");
+  const config = await loadConfig(configPath);
+  if (!withCompanion) return { configPath, config, port: 1 };
+  const running = await startHostCompanion({ port: 0, host: "127.0.0.1", name: config.name, log: () => {} });
+  t.after(() => running.close());
+  return { configPath, config, port: running.port };
+}
+
+void test("parses a Vita address with an optional port", () => {
+  assert.deepEqual(parseVitaAddress("192.168.1.177"), { host: "192.168.1.177", port: 8787 });
+  assert.deepEqual(parseVitaAddress("192.168.1.177:9000"), { host: "192.168.1.177", port: 9000 });
+  assert.equal(parseVitaAddress("192.168.1.177/link"), undefined);
+});
+
+void test("first use writes a config with a generated id", async (t) => {
+  const { configPath, config } = await setup(t, false);
+  assert.match(config.id, /^[0-9a-f-]{36}$/u);
+  assert.deepEqual(JSON.parse(await readFile(configPath, "utf8")), config);
+  assert.deepEqual(await loadConfig(configPath), config);
+});
+
+void test("links, then remembers the Vita", async (t) => {
+  const { configPath, config, port } = await setup(t);
+  const vita = await stubVita(t, await fixture("link-ok"));
+
+  const outcome = await linkVita(`127.0.0.1:${vita.port}`, { configPath, port, advertise: "192.168.1.20" });
+
+  assert.ok(outcome.ok, outcome.message);
+  assert.deepEqual(vita.received, [
+    {
+      method: "POST",
+      url: "/link",
+      body: { protocolVersion: 1, id: config.id, name: config.name, url: `http://192.168.1.20:${port}/` },
+    },
+  ]);
+  assert.deepEqual((await loadConfig(configPath)).vitas, ["127.0.0.1"]);
+
+  await linkVita(`127.0.0.1:${vita.port}`, { configPath, port });
+  assert.deepEqual((await loadConfig(configPath)).vitas, ["127.0.0.1"]);
+});
+
+void test("advertises the address routed to the Vita by default", async (t) => {
+  const { configPath, port } = await setup(t);
+  const vita = await stubVita(t, await fixture("link-ok"));
+  await linkVita(`127.0.0.1:${vita.port}`, { configPath, port });
+  assert.equal(vita.received[0]?.body.url, `http://127.0.0.1:${port}/`);
+});
+
+void test("reports a protocol version mismatch and saves nothing", async (t) => {
+  const { configPath, port } = await setup(t);
+  const vita = await stubVita(t, await fixture("link-version-mismatch"));
+
+  const outcome = await linkVita(`127.0.0.1:${vita.port}`, { configPath, port });
+
+  assert.deepEqual(outcome, {
+    ok: false,
+    message:
+      "VitaDeck refused the link (unsupported_protocol_version): VitaDeck speaks Host Control protocol version 1.",
+    retry: false,
+  });
+  assert.deepEqual((await loadConfig(configPath)).vitas, []);
+});
+
+void test("a relink asks VitaDeck to update its link only, and keeps the Vita", async (t) => {
+  const { configPath, config, port } = await setup(t);
+  await saveConfig(configPath, { ...config, vitas: ["127.0.0.1"] });
+  const vita = await stubVita(t, await fixture("link-ok"));
+
+  const outcome = await linkVita(`127.0.0.1:${vita.port}`, { configPath, port, relink: true });
+
+  assert.ok(outcome.ok, outcome.message);
+  assert.match(outcome.message, /^Relinked /u);
+  assert.equal(vita.received[0]?.body.relink, true);
+  assert.deepEqual((await loadConfig(configPath)).vitas, ["127.0.0.1"]);
+});
+
+void test("a Vita that forgot this computer is dropped on relink", async (t) => {
+  const { configPath, config, port } = await setup(t);
+  await saveConfig(configPath, { ...config, vitas: ["127.0.0.1", "192.168.1.50"] });
+  const vita = await stubVita(t, await fixture("link-relink-unknown"));
+
+  const outcome = await linkVita(`127.0.0.1:${vita.port}`, { configPath, port, relink: true });
+
+  assert.ok(!outcome.ok && !outcome.retry);
+  assert.match(outcome.message, /forgot this computer/u);
+  assert.deepEqual((await loadConfig(configPath)).vitas, ["192.168.1.50"]);
+});
+
+void test("reports an unreachable Vita", async (t) => {
+  const { configPath, port } = await setup(t);
+  const outcome = await linkVita(`127.0.0.1:${await freePort()}`, { configPath, port });
+
+  assert.ok(!outcome.ok && outcome.retry);
+  assert.match(
+    outcome.message,
+    /^Could not reach VitaDeck at http:\/\/127\.0\.0\.1:\d+\/link \(.*\)\. Check that Upload and link is on/u,
+  );
+});
+
+void test("refuses to link before start is running", async (t) => {
+  const { configPath } = await setup(t, false);
+  const outcome = await linkVita("127.0.0.1", { configPath, port: await freePort() });
+
+  assert.equal(outcome.ok, false);
+  assert.match(
+    outcome.message,
+    /^No Host Companion answers on port \d+ .*Run `vitadeck-host-companion start` first\.$/u,
+  );
+});
+
+void test("rejects a wrongly typed config field", async (t) => {
+  const { configPath } = await setup(t, false);
+  await writeFile(configPath, JSON.stringify({ port: "8797" }));
+  await assert.rejects(loadConfig(configPath), /"port" has the wrong type/u);
+});

